// ── Dark mode ───────────────────────────────────────────────────────
// The legend renders inside the dark Validation-Rules page; the
// light-theme card (#f8fafc bg, #1f2937 title, pastel severity pills)
// produces a washed-out cream card. Override to a dark surface with
// translucent tinted pills that still convey the severity colour but
// don't fight the page background.
body.body--dark {
  .severity-legend-card {
    background: #1a1d24;
    border-color: rgba(255, 255, 255, 0.06);
  }

  .legend-title {
    color: #e4e4e7;
  }

  // Quasar's text-grey-8 utility class would override our color, so
  // we use :deep + !important to win the specificity battle without
  // changing the markup. Slate-400 matches the rest of the page.
  :deep(.legend-text.text-grey-8) {
    color: #94a3b8 !important;
  }

  .severity-pill {
    &.severity-fatal {
      background: rgba(239, 68, 68, 0.18);
      color: #fca5a5;
    }
    &.severity-error {
      background: rgba(249, 115, 22, 0.18);
      color: #fdba74;
    }
    &.severity-warning {
      background: rgba(245, 158, 11, 0.18);
      color: #fcd34d;
    }
    &.severity-info {
      background: rgba(59, 130, 246, 0.18);
      color: #93c5fd;
    }
  }
}
</style>
