<template>
  <div class="validation-rules-page q-gutter-y-md">
    <!-- Tolgee static-extraction whitelist (BOL-432).
         These keys are passed to child components via dynamic props
         (`titleKey`, `subtitleKey`) so Tolgee's Vite extractor can't
         see them. Listing them here as literal $t() calls keeps
         them in the extracted set. -->
    <span v-if="false" data-test="i18n-discoverable-list">
      {{ $t('validation_show_details') }}
      {{ $t('validation_col_details') }}
      {{ $t('validation_filter_version') }}
      {{ $t('validation_policy_versions_title') }}
      {{ $t('validation_policy_versions_subtitle') }}
      {{ $t('validation_policy_profiles_title') }}
      {{ $t('validation_policy_profiles_subtitle') }}
      {{ $t('validation_status_current') }}
      {{ $t('validation_status_deprecated') }}
      {{ $t('validation_status_eol') }}
      {{ $t('validation_severity_fatal') }}
      {{ $t('validation_severity_error') }}
      {{ $t('validation_severity_warning') }}
      {{ $t('validation_severity_info') }}
      {{ $t('validation_severity_default_label') }}
    </span>
    <div class="page-header">
      <h2 class="page-title">{{ $t('validation_rules_page_title') }}</h2>
      <p class="page-subtitle text-grey-7">
        {{ $t('validation_rules_page_subtitle') }}
      </p>
    </div>

    <!-- BOL-440: Always-visible business-questions wizard.
         Sits ABOVE the acceptance-policy cards because it owns the
         high-level configuration; the cards remain as the advanced
         editing surface for fine-grained version/profile lists. -->
    <BusinessQuestionsWizard
      doc-type="INVOICE"
      @saved="onWizardSaved"
    />

    <!-- BOL-429-B: Acceptance policy — XRechnung versions -->
    <AcceptancePolicyCard
      v-if="!policyLoading"
      kind="versions"
      title-key="validation_policy_versions_title"
      subtitle-key="validation_policy_versions_subtitle"
      :entries="versionEntries"
      :initial-accepted="acceptedVersions"
      :saving="savingPolicyKind === 'versions'"
      @save="(v) => savePolicy('versions', v)"
    />

    <!-- BOL-429-B: Acceptance policy — ZUGFeRD/Factur-X profiles -->
    <AcceptancePolicyCard
      v-if="!policyLoading"
      kind="profiles"
      title-key="validation_policy_profiles_title"
      subtitle-key="validation_policy_profiles_subtitle"
      :entries="profileEntries"
      :initial-accepted="acceptedProfiles"
      :saving="savingPolicyKind === 'profiles'"
      @save="(v) => savePolicy('profiles', v)"
    />

    <!-- BOL-425: Severity legend (collapsible, dismiss persists in localStorage) -->
    <SeverityLegendCard />

    <!-- Filter bar -->
    <div class="filter-bar row q-gutter-md items-end">
      <q-select
        outlined
        dense
        clearable
        v-model="filter.layer"
        :options="layerOptions"
        :label="$t('validation_filter_layer')"
        emit-value
        map-options
        style="min-width: 180px"
        data-test="filter-layer"
      />
      <q-select
        outlined
        dense
        clearable
        v-model="filter.profile"
        :options="profileOptions"
        :label="$t('validation_filter_profile')"
        emit-value
        map-options
        style="min-width: 200px"
        data-test="filter-profile"
      />
      <!-- BOL-424: Version multi-filter, populated from /validation_versions -->
      <q-select
        outlined
        dense
        clearable
        multiple
        v-model="filter.versions"
        :options="versionFilterOptions"
        :label="$t('validation_filter_version')"
        emit-value
        map-options
        use-chips
        style="min-width: 220px"
        data-test="filter-version"
      />
      <q-input
        outlined
        dense
        debounce="300"
        v-model="filter.search"
        :label="$t('validation_filter_search')"
        style="min-width: 240px"
        data-test="filter-search"
      >
        <template v-slot:append>
          <q-icon name="search" />
        </template>
      </q-input>
      <q-space />
      <q-btn
        v-if="overrideCount > 0"
        flat
        no-caps
        size="sm"
        color="grey-8"
        icon="mdi:undo-variant"
        :label="`${$t('validation_reset_all_overrides')} (${overrideCount})`"
        data-test="reset-all-overrides"
        @click="onResetAllOverrides"
      />
      <div class="text-caption text-grey-7" data-test="filter-counter">
        {{ filteredRows.length }} / {{ allRows.length }}
        {{ $t('validation_rules_count_label') }}
      </div>
    </div>

    <!-- Rules table -->
    <DocBitsTable
      :rows="filteredRows"
      :columns="columns"
      row-key="code"
      table-id="einvoice_validation_rules_table"
      :loading="loading"
      :features="{
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: true,
        pagination: true,
        columnReorder: false,
        stickyLastColumn: true,
      }"
      no-data-label="no_record_found"
      flat-style
      table-height="600px"
    >
      <template #body-cell-expand="{ row }">
        <!-- Compact details CTA: inline-SVG chevron eliminates the
             MDI-bundle render drift seen at small sizes in Chrome
             (BOL-438 fix pattern). Label kept short (DE: "Details",
             not "Details anzeigen") so the column doesn't dominate
             the 1 637-row table; aria-label carries the full text
             for screen readers. -->
        <button
          v-if="hasDetails(row)"
          type="button"
          class="details-cta"
          :data-test="`row-expand-${row.code}`"
          :aria-label="$t('validation_show_details')"
          @click.stop="openDetail(row)"
        >
          <span class="details-cta-label">{{ $t('validation_col_details') }}</span>
          <svg
            class="details-cta-chevron"
            viewBox="0 0 24 24"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
          >
            <path
              d="M9.29 6.71a1 1 0 000 1.41L13.17 12l-3.88 3.88a1 1 0 101.42 1.41l4.59-4.59a1 1 0 000-1.41l-4.59-4.59a1 1 0 00-1.42 0z"
              fill="currentColor"
            />
          </svg>
        </button>
      </template>

      <template #body-cell-layer="{ row }">
        <q-chip
          dense
          :data-test="`row-layer-${row.code}`"
          :class="`layer-chip layer-${row.layer.toLowerCase()}`"
        >
          {{ row.layer }}
        </q-chip>
      </template>

      <template #body-cell-effective_severity="{ row }">
        <div class="severity-cell">
          <q-select
            dense
            outlined
            v-model="row.effective_severity"
            :options="severityOptions"
            emit-value
            map-options
            :data-test="`row-severity-${row.code}`"
            :class="
              row.override
                ? 'severity-select severity-overridden'
                : 'severity-select'
            "
            @update:model-value="(v: any) => onSeverityChange(row, v as RuleSeverity)"
          />
          <!-- BOL-425: per-row reset to KoSIT default when override is active -->
          <q-btn
            v-if="row.override"
            flat
            dense
            round
            size="sm"
            icon="mdi:undo-variant"
            color="amber-9"
            :title="`${$t('validation_clear_override')} → ${row.default_severity}`"
            :data-test="`row-clear-${row.code}`"
            @click="onSeverityChange(row, null)"
          />
        </div>
        <div
          v-if="row.override"
          class="text-caption text-grey-7"
          :data-test="`row-default-${row.code}`"
        >
          {{ $t('validation_default_severity_label') }}: {{ row.default_severity }}
        </div>
      </template>

    </DocBitsTable>

    <!-- BOL-424: rule detail dialog. Opened from the row "Details" button. -->
    <q-dialog v-model="detailDialogOpen" no-backdrop-dismiss>
      <q-card class="rule-detail-dialog" data-test="rule-detail-dialog">
        <q-card-section class="detail-dialog-header q-pa-md">
          <div class="detail-header-row">
            <q-chip
              v-if="detailRow"
              dense
              :class="`layer-chip layer-${detailRow.layer.toLowerCase()}`"
            >
              {{ detailRow.layer }}
            </q-chip>
            <code class="detail-dialog-code">{{ detailRow?.code }}</code>
            <q-space />
            <q-btn
              flat
              dense
              round
              icon="close"
              data-test="rule-detail-close"
              @click="detailDialogOpen = false"
            />
          </div>
          <div v-if="detailRow" class="detail-meta-strip">
            <span class="meta-item">
              <span class="meta-label">{{ $t('validation_col_profile') }}</span>
              <span class="meta-value">{{ detailRow.profile }}</span>
            </span>
            <span v-if="detailRow.version" class="meta-item">
              <span class="meta-label">{{ $t('validation_col_version') }}</span>
              <span class="meta-value">{{ detailRow.version }}</span>
            </span>
            <span class="meta-item">
              <span class="meta-label">{{ $t('validation_severity_default_label') }}</span>
              <span :class="['meta-pill', `pill-${detailRow.default_severity}`]">
                {{ severityLabel(detailRow.default_severity) }}
              </span>
            </span>
          </div>
        </q-card-section>
        <q-separator />
        <q-card-section class="q-pa-none">
          <RuleDetailBox v-if="detailRow" :row="detailRow" />
        </q-card-section>
      </q-card>
    </q-dialog>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import { docTypeApiService, validationRulesApiService } from 'src/services';
import type {
  ProfileRegistryEntry,
  RuleSeverity,
  ValidationRuleRow,
  VersionRegistryEntry,
} from 'src/services/settings/ValidationRulesApiService';
import AcceptancePolicyCard from 'src/pages/Settings/Components/ValidationRules/AcceptancePolicyCard.vue';
import SeverityLegendCard from 'src/pages/Settings/Components/ValidationRules/SeverityLegendCard.vue';
import RuleDetailBox from 'src/pages/Settings/Components/ValidationRules/RuleDetailBox.vue';
import BusinessQuestionsWizard from 'src/pages/Settings/Components/ValidationRules/BusinessQuestionsWizard.vue';
import { deepLinkSearchTerm } from 'src/utils/settings-deep-link';

interface Filter {
  layer: string | null;
  profile: string | null;
  versions: string[];
  search: string;
}

// BOL-429: per-DocType acceptance policy. Today the Settings page
// scopes the policy to the INVOICE doc-type (the only DocType that
// can have XRECHNUNG_VALIDATION_ENABLED on it). When we expand to
// CREDIT_NOTE/etc. the doc-type selector lives here.
const POLICY_DOC_TYPE = 'INVOICE';
const ATTR_ACCEPTED_VERSIONS = 'XRECHNUNG_ACCEPTED_VERSIONS';
const ATTR_ACCEPTED_PROFILES = 'ZUGFERD_ACCEPTED_PROFILES';

interface PolicyEntry {
  key: string;
  label: string;
  note?: string | null;
  releasedOn?: string | null;
  statusChip?: { label: string; color: string; textColor: string } | null;
}

export default defineComponent({
  name: 'ValidationRulesList',
  components: {
    DocBitsTable,
    AcceptancePolicyCard,
    SeverityLegendCard,
    RuleDetailBox,
    BusinessQuestionsWizard,
  },
  data() {
    return {
      loading: false,
      allRows: [] as ValidationRuleRow[],
      filter: {
        layer: null,
        profile: null,
        versions: [] as string[],
        search: '',
      } as Filter,
      severityOptions: [
        { label: 'Fatal', value: 'fatal' as RuleSeverity },
        { label: 'Error', value: 'error' as RuleSeverity },
        { label: 'Warning', value: 'warning' as RuleSeverity },
        { label: 'Info', value: 'info' as RuleSeverity },
      ],
      detailDialogOpen: false,
      detailRow: null as ValidationRuleRow | null,

      // BOL-429: acceptance policy state
      policyLoading: true,
      versionRegistry: [] as VersionRegistryEntry[],
      profileRegistry: [] as ProfileRegistryEntry[],
      acceptedVersions: [] as string[],
      acceptedProfiles: [] as string[],
      savingPolicyKind: null as 'versions' | 'profiles' | null,
    };
  },
  computed: {
    layerOptions() {
      return ['L0', 'L0b', 'L0c', 'L1', 'L2', 'L3', 'L4'].map((v) => ({
        label: v,
        value: v,
      }));
    },
    profileOptions() {
      const profiles = new Set(this.allRows.map((r) => r.profile));
      return Array.from(profiles)
        .sort()
        .map((p) => ({ label: p, value: p }));
    },
    versionFilterOptions() {
      // Distinct versions actually present in the catalog.
      const versions = new Set(
        this.allRows
          .map((r) => r.version)
          .filter((v): v is string => v !== null && v !== undefined),
      );
      return Array.from(versions)
        .sort()
        .map((v) => ({ label: v, value: v }));
    },
    overrideCount(): number {
      return this.allRows.filter((r) => r.override).length;
    },
    versionEntries(): PolicyEntry[] {
      return this.versionRegistry.map((v) => ({
        key: v.version,
        label: v.label,
        note: v.note,
        releasedOn: v.released_on,
        statusChip: this.statusChip(v.status),
      }));
    },
    profileEntries(): PolicyEntry[] {
      return this.profileRegistry.map((p) => ({
        key: p.profile,
        label: p.label,
        note: p.note,
        statusChip: p.en16931_conformant
          ? null
          : {
              label: this.$t('validation_policy_not_en16931'),
              color: 'amber-2',
              textColor: 'amber-9',
            },
      }));
    },
    columns(): any[] {
      return [
        {
          name: 'expand',
          label: this.$t('validation_col_details'),
          field: () => '',
          align: 'center',
          style: 'width: 130px',
          headerStyle: 'width: 130px',
        },
        {
          name: 'layer',
          label: this.$t('validation_col_layer'),
          field: 'layer',
          align: 'left',
          sortable: true,
        },
        {
          name: 'code',
          label: this.$t('validation_col_code'),
          field: 'code',
          align: 'left',
          sortable: true,
          classes: 'col-mono',
        },
        {
          name: 'profile',
          label: this.$t('validation_col_profile'),
          field: 'profile',
          align: 'left',
          sortable: true,
        },
        {
          name: 'version',
          label: this.$t('validation_col_version'),
          field: (row: ValidationRuleRow) => row.version || '—',
          align: 'left',
          sortable: true,
        },
        {
          name: 'field',
          label: this.$t('validation_col_field'),
          field: (row: ValidationRuleRow) => row.field || '—',
          align: 'left',
        },
        {
          name: 'effective_severity',
          label: this.$t('validation_col_severity'),
          field: 'effective_severity',
          align: 'left',
          sortable: true,
        },
      ];
    },
    filteredRows(): ValidationRuleRow[] {
      const search = this.filter.search.trim().toLowerCase();
      const versions = new Set(this.filter.versions);
      return this.allRows.filter((r) => {
        if (this.filter.layer && r.layer !== this.filter.layer) return false;
        if (this.filter.profile && r.profile !== this.filter.profile) return false;
        if (versions.size > 0) {
          if (!r.version || !versions.has(r.version)) return false;
        }
        if (search) {
          const haystack =
            `${r.code} ${r.field || ''} ${r.profile} ${r.description || ''}`.toLowerCase();
          if (!haystack.includes(search)) return false;
        }
        return true;
      });
    },
  },
  mounted() {
    // DOCB-14316: arrived from a Touchless fix step. The card knows which
    // field failed and which rule rejected it; without seeding the filter the
    // consultant lands on the full catalog and searches for it by hand, which
    // is the "dead-ish link" half of the same complaint.
    const term = deepLinkSearchTerm(this.$route?.query);
    if (term) this.filter.search = term;
    this.load();
    this.loadPolicy();
  },
  methods: {
    /** Re-load the org's policy state after a wizard save — the wizard
     *  writes through to `XRECHNUNG_ACCEPTED_VERSIONS` /
     *  `ZUGFERD_ACCEPTED_PROFILES` plus rule-overrides, so the
     *  acceptance-policy cards + rule table below need to refresh to
     *  show the new values. */
    onWizardSaved() {
      this.loadPolicy();
      this.load();
    },
    statusChip(status: 'current' | 'deprecated' | 'eol') {
      if (status === 'current') {
        return {
          label: this.$t('validation_status_current'),
          color: 'green-2',
          textColor: 'green-9',
        };
      }
      if (status === 'deprecated') {
        return {
          label: this.$t('validation_status_deprecated'),
          color: 'amber-2',
          textColor: 'amber-9',
        };
      }
      return {
        label: this.$t('validation_status_eol'),
        color: 'red-2',
        textColor: 'red-9',
      };
    },
    hasDetails(row: ValidationRuleRow): boolean {
      return Boolean(
        row.description ||
          row.method ||
          row.triggered_when ||
          row.example_valid ||
          row.example_invalid ||
          (row.references && row.references.length) ||
          row.rationale,
      );
    },
    openDetail(row: ValidationRuleRow) {
      this.detailRow = row;
      this.detailDialogOpen = true;
    },
    severityLabel(severity: RuleSeverity | null): string {
      if (!severity) return '—';
      const map: Record<string, string> = {
        fatal: this.$t('validation_severity_fatal'),
        error: this.$t('validation_severity_error'),
        warning: this.$t('validation_severity_warning'),
        info: this.$t('validation_severity_info'),
      };
      return map[severity] || severity;
    },
    async load() {
      this.loading = true;
      try {
        const resp = await validationRulesApiService.list();
        this.allRows = resp?.data || [];
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.loading = false;
      }
    },
    async loadPolicy() {
      this.policyLoading = true;
      try {
        const [registries, attrs] = await Promise.all([
          validationRulesApiService.listVersions(),
          docTypeApiService.getAttributesByDocKey({
            doc_type: POLICY_DOC_TYPE,
          }),
        ]);
        this.versionRegistry = registries.versions || [];
        this.profileRegistry = registries.profiles || [];
        this.acceptedVersions = this.parseJsonAttr(
          attrs,
          ATTR_ACCEPTED_VERSIONS,
        );
        // DOCB-12181: legacy Wizard runs persisted lowercase profile
        // keys (`["xrechnung"]`) while the registry + checkbox keys
        // are UPPERCASE. Normalise on read so existing rows render
        // with the correct checkbox state without a DB migration.
        // Idempotent for new data which is already UPPERCASE.
        this.acceptedProfiles = this.parseJsonAttr(
          attrs,
          ATTR_ACCEPTED_PROFILES,
        ).map((p) => p.toUpperCase());
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.policyLoading = false;
      }
    },
    parseJsonAttr(attrsResponse: any, key: string): string[] {
      const list = attrsResponse?.data || attrsResponse?.attributes || [];
      const found = list.find?.((a: any) => a.attribute_key === key);
      const raw = found?.attribute_value;
      if (!raw) return [];
      try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed)
          ? parsed.map((v: any) => String(v))
          : [];
      } catch {
        return [];
      }
    },
    async savePolicy(kind: 'versions' | 'profiles', accepted: string[]) {
      this.savingPolicyKind = kind;
      const attributeKey =
        kind === 'versions' ? ATTR_ACCEPTED_VERSIONS : ATTR_ACCEPTED_PROFILES;
      try {
        // `doc_type_key` is the form-field name the backend expects
        // (`Form(...)` parameter in routers/document_and_fields.py:3286).
        // Earlier this payload used `doc_type` which silently dropped
        // through `DocTypeApiService.setAttribute()`'s naive
        // Object.entries() loop, producing a 422 "Field required:
        // doc_type_key" response.
        await docTypeApiService.setAttribute({
          doc_type_key: POLICY_DOC_TYPE,
          attribute_key: attributeKey,
          attribute_value: JSON.stringify(accepted),
        });
        if (kind === 'versions') {
          this.acceptedVersions = [...accepted];
        } else {
          this.acceptedProfiles = [...accepted];
        }
        notify.success(this.$t('validation_policy_saved'));
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as any));
      } finally {
        this.savingPolicyKind = null;
      }
    },
    async onSeverityChange(row: ValidationRuleRow, value: RuleSeverity | null) {
      // Optimistic UI: flip the row immediately, revert on failure.
      const previousEffective = row.effective_severity;
      const previousOverride = row.override;
      row.override = value;
      row.effective_severity = value || row.default_severity;

      try {
        await validationRulesApiService.setOverride(row.code, value);
        notify.success(this.$t('validation_override_saved'));
      } catch (err) {
        row.override = previousOverride;
        row.effective_severity = previousEffective;
        notify.error(ApiExceptions.getErrorMessage(err as any));
      }
    },
    async onResetAllOverrides() {
      const overridden = this.allRows.filter((r) => r.override);
      if (overridden.length === 0) return;
      const confirmed = window.confirm(
        this.$t('validation_reset_all_confirm', {
          count: overridden.length,
        }),
      );
      if (!confirmed) return;

      // Snapshot for revert
      const snapshot = overridden.map((r) => ({
        row: r,
        prevEffective: r.effective_severity,
        prevOverride: r.override,
      }));

      // Optimistic clear
      for (const s of snapshot) {
        s.row.override = null;
        s.row.effective_severity = s.row.default_severity;
      }

      const failed: typeof snapshot = [];
      await Promise.allSettled(
        snapshot.map(async (s) => {
          try {
            await validationRulesApiService.setOverride(s.row.code, null);
          } catch (err) {
            failed.push(s);
          }
        }),
      );

      if (failed.length === 0) {
        notify.success(
          this.$t('validation_reset_all_success', { count: snapshot.length }),
        );
      } else {
        // Revert the failed ones
        for (const s of failed) {
          s.row.override = s.prevOverride;
          s.row.effective_severity = s.prevEffective;
        }
        notify.error(
          this.$t('validation_reset_all_partial_failure', {
            failed: failed.length,
            total: snapshot.length,
          }),
        );
      }
    },
  },
});
</script>

