<script lang="ts">
import { defineComponent, type PropType } from 'vue';

export interface PolicyEntry {
  key: string;
  label: string;
  note?: string | null;
  releasedOn?: string | null;
  statusChip?: {
    label: string;
    color: string;
    textColor: string;
  } | null;
}

export default defineComponent({
  name: 'AcceptancePolicyCard',
  props: {
    kind: {
      type: String as PropType<'versions' | 'profiles'>,
      required: true,
    },
    titleKey: { type: String, required: true },
    subtitleKey: { type: String, required: true },
    entries: {
      type: Array as PropType<PolicyEntry[]>,
      required: true,
    },
    /** The currently-saved accepted keys (loaded from DocType attr). */
    initialAccepted: {
      type: Array as PropType<string[]>,
      required: true,
    },
    saving: { type: Boolean, default: false },
  },
  emits: ['save'],
  data() {
    return {
      accepted: [...this.initialAccepted] as string[],
    };
  },
  computed: {
    acceptedCount(): number {
      return this.accepted.length;
    },
    anyAccepted(): boolean {
      return this.accepted.length > 0;
    },
    dirty(): boolean {
      const a = [...this.accepted].sort();
      const b = [...this.initialAccepted].sort();
      if (a.length !== b.length) return true;
      return a.some((v, i) => v !== b[i]);
    },
  },
  watch: {
    initialAccepted: {
      handler(next: string[]) {
        this.accepted = [...next];
      },
    },
  },
  methods: {
    toggle(key: string, on: boolean) {
      if (on) {
        if (!this.accepted.includes(key)) this.accepted.push(key);
      } else {
        this.accepted = this.accepted.filter((k) => k !== key);
      }
    },
    acceptAll() {
      // DOCB-12181: emit save immediately. Previously this only
      // mutated local state and waited for an explicit Save click —
      // users reasonably assumed "Accept all" *was* the save, never
      // pressed Save, then saw the watcher on `initialAccepted`
      // restore the DB-truth and concluded "something is overwriting
      // my settings". One click = one persist now.
      this.accepted = this.entries.map((e) => e.key);
      this.$emit('save', [...this.accepted]);
    },
    clear() {
      // Same rationale as acceptAll: a destructive one-click action
      // should persist immediately, not silently revert.
      this.accepted = [];
      this.$emit('save', [...this.accepted]);
    },
    save() {
      this.$emit('save', [...this.accepted]);
    },
  },
});
</script>

