<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import BusinessQuestionsProfileCard from 'src/pages/Settings/Components/ValidationRules/BusinessQuestionsProfileCard.vue';
import BusinessQuestionsGroupStep from 'src/pages/Settings/Components/ValidationRules/BusinessQuestionsGroupStep.vue';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import { policyWizardApiService } from 'src/services';
import type {
  ProfileDef,
  QuestionDef,
  QuestionGroup,
  ResolvedPolicy,
  RuleCategory,
  WizardProfileId,
  Preset,
} from 'src/services/settings/PolicyWizardApiService';

type StepKey =
  | 'setup'
  | 'group_a'
  | 'group_b'
  | 'group_c'
  | 'group_d'
  | 'group_e'
  | 'review';

export interface WizardState {
  profile: WizardProfileId | null;
  answers: Record<string, string | string[]>;
  saving: boolean;
  hasSavedState: boolean;
}

const STEP_SEQUENCE_CUSTOM: StepKey[] = [
  'setup',
  'group_a',
  'group_b',
  'group_c',
  'group_d',
  'group_e',
  'review',
];

const STEP_SEQUENCE_QUICK: StepKey[] = ['setup', 'review'];

const STEP_TITLE_KEY: Record<StepKey, string> = {
  setup: 'biz_wizard_step_setup',
  group_a: 'biz_wizard_step_doc_format',
  group_b: 'biz_wizard_step_banking',
  group_c: 'biz_wizard_step_tax',
  group_d: 'biz_wizard_step_identification',
  group_e: 'biz_wizard_step_behavior',
  review: 'biz_wizard_step_review',
};

export default defineComponent({
  name: 'BusinessQuestionsWizard',
  components: {
    BusinessQuestionsProfileCard,
    BusinessQuestionsGroupStep,
  },
  props: {
    docType: { type: String, required: true },
    subDocType: { type: String as PropType<string | null>, default: null },
  },
  emits: ['saved'],
  data() {
    return {
      expanded: false,
      loading: false,
      profiles: [] as ProfileDef[],
      questions: [] as QuestionDef[],
      state: {
        profile: null as WizardProfileId | null,
        answers: {} as Record<string, string | string[]>,
        saving: false,
        hasSavedState: false,
      } as WizardState,
      currentStep: 'setup' as StepKey,
      /** When true, the wizard walks Tier-2 groups even for
       *  non-Custom profiles. Triggered by "Customize answers anyway"
       *  in the review step. */
      applyCustomAnswers: false,
      saveError: '' as string,
      lastSavedAt: null as Date | null,
      /** Live resolved policy from the backend — re-fetched after
       *  every save so the collapsed-card status reflects truth. */
      lastResolved: null as ResolvedPolicy | null,
    };
  },
  computed: {
    /** Profile chosen in step 1; never null after the initial load
     *  because the backend always returns at least the default. */
    selectedProfile(): ProfileDef | null {
      if (!this.state.profile) return null;
      return this.profiles.find((p) => p.id === this.state.profile) ?? null;
    },
    visibleSteps(): Array<{ key: StepKey; titleKey: string }> {
      const seq =
        this.state.profile === 'custom' || this.applyCustomAnswers
          ? STEP_SEQUENCE_CUSTOM
          : STEP_SEQUENCE_QUICK;
      return seq.map((key) => ({ key, titleKey: STEP_TITLE_KEY[key] }));
    },
    currentEyebrow(): string {
      if (!this.state.hasSavedState) {
        return this.$t('biz_wizard_eyebrow_unsaved');
      }
      const label =
        this.selectedProfile?.label_key ?? 'biz_profile_b2b_domestic_label';
      return `${this.$t('biz_wizard_eyebrow_current')} · ${this.$t(label)}`;
    },
    statusLine(): string {
      if (this.state.saving) return this.$t('biz_wizard_saving_status');
      if (this.lastSavedAt) {
        return `${this.$t('biz_wizard_saved_status')} · ${this.$t('biz_wizard_saved_just_now')}`;
      }
      if (!this.state.hasSavedState) {
        return this.$t('biz_wizard_setup_description');
      }
      return this.$t('biz_wizard_saved_status');
    },
    /** Fixed display order for category rows in the review step.
     *  Mirrors `all_categories()` in rule_categories.py. */
    orderedCategories(): RuleCategory[] {
      return [
        'document_format',
        'invoice_structure',
        'identification',
        'tax_and_vat',
        'banking_and_payment',
        'pricing_and_dates',
      ];
    },
    /** What the resolved policy *would* be if we saved right now.
     *  For Quick mode (non-Custom + no apply_custom_answers), this is
     *  the profile baseline. For Custom or "Customize anyway", we'd
     *  need the backend to resolve — but the apply step refreshes
     *  this after save, so the review here is a best-effort preview
     *  driven by the locally-known profile baseline. */
    previewedResolved(): ResolvedPolicy {
      if (this.lastResolved && !this.dirty) {
        return this.lastResolved;
      }
      const p = this.selectedProfile;
      if (!p) {
        return {
          profile: 'b2b_domestic',
          category_presets: {} as Record<RuleCategory, Preset>,
          rule_overrides: {},
          accepted_versions: [],
          accepted_profiles: [],
          vies_enabled: false,
          blocking_enabled: false,
          supplier_notification_enabled: false,
        };
      }
      return {
        profile: p.id,
        category_presets: { ...p.category_presets },
        rule_overrides: {},
        accepted_versions: [...p.accepted_versions],
        accepted_profiles: [...p.accepted_profiles],
        vies_enabled: p.vies_enabled,
        blocking_enabled: p.blocking_enabled,
        supplier_notification_enabled: p.supplier_notification_enabled,
      };
    },
    /** True when local state diverges from the last-saved-state.
     *  Drives the disable-on-clean save button (n/a here; we leave
     *  it always enabled in review so the consultant can confirm). */
    dirty(): boolean {
      if (!this.lastResolved) return true;
      return (
        this.state.profile !== this.lastResolved.profile ||
        this.applyCustomAnswers
      );
    },
  },
  mounted() {
    void this.load();
  },
  methods: {
    async load(): Promise<void> {
      this.loading = true;
      try {
        const [defs, state] = await Promise.all([
          policyWizardApiService.getDefinitions(),
          policyWizardApiService.getState(this.docType, this.subDocType),
        ]);
        this.profiles = [...defs.profiles].sort((a, b) =>
          a.is_default && !b.is_default ? -1 : 0,
        );
        // Backend already returns profiles in sort_order; keep that
        // order but lift the default to the top so the eye lands on
        // it (B2B Domestic should be the first option, not buried).
        this.profiles = defs.profiles;
        this.questions = defs.questions;
        this.state.profile = state.profile;
        this.state.answers = state.answers;
        this.state.hasSavedState = state.has_saved_state;
        this.lastResolved = state.resolved;
      } catch (err) {
        notify.error(ApiExceptions.getErrorMessage(err as never));
      } finally {
        this.loading = false;
      }
    },

    questionsByGroup(group: QuestionGroup): QuestionDef[] {
      return this.questions
        .filter((q) => q.group === group)
        .sort((a, b) => a.sort_order - b.sort_order);
    },

    isStepDone(step: StepKey, idx: number): boolean {
      const currentIdx = this.visibleSteps.findIndex(
        (s) => s.key === this.currentStep,
      );
      return idx < currentIdx;
    },

    goToStep(step: StepKey): void {
      // Only allow jumping to a step that's part of the current
      // sequence (custom vs. quick) and not forward past the cursor.
      const ordered = this.visibleSteps.map((s) => s.key);
      const currentIdx = ordered.indexOf(this.currentStep);
      const targetIdx = ordered.indexOf(step);
      if (targetIdx >= 0 && targetIdx <= currentIdx + 1) {
        this.currentStep = step;
      }
    },

    open(): void {
      this.expanded = true;
      // Re-load on each open so the wizard reflects the canonical
      // server state — protects against multi-tab edits.
      void this.load();
      this.currentStep = 'setup';
      this.applyCustomAnswers = false;
      this.saveError = '';
    },

    cancel(): void {
      this.expanded = false;
      this.saveError = '';
      // Reset transient state; lastResolved stays so the collapsed
      // card keeps showing the saved profile.
      this.applyCustomAnswers = false;
    },

    selectProfile(id: WizardProfileId): void {
      this.state.profile = id;
      // Reset Custom-overlay flag on profile switch unless the new
      // pick IS custom (then we keep overlay on by definition).
      this.applyCustomAnswers = id === 'custom';
    },

    enableCustomAnswers(): void {
      this.applyCustomAnswers = true;
      // Jump to first Tier-2 step so the consultant can adjust.
      this.currentStep = 'group_a';
    },

    nextStep(): void {
      const ordered = this.visibleSteps.map((s) => s.key);
      const idx = ordered.indexOf(this.currentStep);
      if (idx < 0 || idx >= ordered.length - 1) return;
      this.currentStep = ordered[idx + 1];
    },

    prevStep(): void {
      const ordered = this.visibleSteps.map((s) => s.key);
      const idx = ordered.indexOf(this.currentStep);
      if (idx <= 0) {
        // Cancel and collapse — user is at the first step and
        // hits Back again.
        this.cancel();
        return;
      }
      this.currentStep = ordered[idx - 1];
    },

    async save(): Promise<void> {
      if (!this.state.profile) return;
      this.state.saving = true;
      this.saveError = '';
      try {
        const resp = await policyWizardApiService.apply(
          this.state.profile,
          this.state.answers,
          this.docType,
          this.subDocType,
          this.applyCustomAnswers,
        );
        this.lastResolved = resp.resolved;
        this.state.hasSavedState = true;
        this.lastSavedAt = new Date();
        notify.success(this.$t('biz_wizard_saved_status'));
        this.$emit('saved', resp);
        // Collapse + close after successful save
        this.expanded = false;
        this.applyCustomAnswers = false;
      } catch (err) {
        this.saveError = ApiExceptions.getErrorMessage(err as never);
        notify.error(this.saveError || this.$t('biz_wizard_save_error'));
      } finally {
        this.state.saving = false;
      }
    },

    /** Preset for a given category in the current preview. Used by
     *  the review step's category list. */
    previewPreset(cat: RuleCategory): Preset {
      return this.previewedResolved.category_presets[cat] ?? 'standard';
    },
  },
});
</script>

