<template>
  <div class="group-step">
    <header class="group-step-header">
      <div class="group-step-eyebrow">
        {{ $t('biz_wizard_step_eyebrow') }}
      </div>
      <h3 class="group-step-title">{{ $t(titleKey) }}</h3>
      <p v-if="descriptionKey" class="group-step-description">
        {{ $t(descriptionKey) }}
      </p>
    </header>

    <ul class="group-step-questions">
      <li
        v-for="question in questions"
        :key="question.id"
        class="group-step-question"
      >
        <div class="question-prompt-row">
          <span class="question-id">{{ question.id }}</span>
          <span class="question-label">{{ $t(question.label_key) }}</span>
          <button
            v-if="question.help_key"
            type="button"
            class="question-help"
            :aria-label="$t('biz_wizard_help_aria')"
            @click="toggleHelp(question.id)"
          >
            <svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
              <path
                d="M11 18h2v-2h-2v2zm1-16C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 18a8 8 0 110-16 8 8 0 010 16zM12 6a4 4 0 00-4 4h2a2 2 0 014 0c0 2-3 1.75-3 5h2c0-2.25 3-2.5 3-5a4 4 0 00-4-4z"
                fill="currentColor"
              />
            </svg>
          </button>
        </div>

        <p
          v-if="question.help_key && openHelp.has(question.id)"
          class="question-help-text"
        >
          {{ $t(question.help_key) }}
        </p>

        <!-- yes_no — pair of radio pills -->
        <div
          v-if="question.answer_type === 'yes_no'"
          class="option-row option-row--inline"
        >
          <button
            v-for="opt in question.options"
            :key="opt"
            type="button"
            class="option-pill"
            :class="{ 'option-pill--on': isSelected(question.id, opt) }"
            :data-test="`biz-answer-${question.id}-${opt}`"
            @click="setAnswer(question.id, opt)"
          >
            {{ optionLabel(question.id, opt) }}
          </button>
        </div>

        <!-- single_choice / tolerance — same UI as yes_no -->
        <div
          v-else-if="
            question.answer_type === 'single_choice' ||
            question.answer_type === 'tolerance'
          "
          class="option-row option-row--inline"
        >
          <button
            v-for="opt in question.options"
            :key="opt"
            type="button"
            class="option-pill"
            :class="{ 'option-pill--on': isSelected(question.id, opt) }"
            :data-test="`biz-answer-${question.id}-${opt}`"
            @click="setAnswer(question.id, opt)"
          >
            {{ optionLabel(question.id, opt) }}
          </button>
        </div>

        <!-- multi_select — checkbox-style pills -->
        <div
          v-else-if="question.answer_type === 'multi_select'"
          class="option-row option-row--wrap"
        >
          <button
            v-for="opt in question.options"
            :key="opt"
            type="button"
            class="option-pill option-pill--multi"
            :class="{ 'option-pill--on': isInMultiSelect(question.id, opt) }"
            :data-test="`biz-answer-${question.id}-${opt}`"
            @click="toggleMultiSelect(question.id, opt)"
          >
            <span class="option-pill-check" aria-hidden="true">
              <svg
                v-if="isInMultiSelect(question.id, opt)"
                viewBox="0 0 24 24"
                xmlns="http://www.w3.org/2000/svg"
              >
                <path
                  d="M9 16.17l-3.88-3.88-1.41 1.41L9 19 21 7l-1.41-1.41z"
                  fill="currentColor"
                />
              </svg>
            </span>
            {{ optionLabel(question.id, opt) }}
          </button>
        </div>
      </li>
    </ul>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { QuestionDef } from 'src/services/settings/PolicyWizardApiService';

type AnswerMap = Record<string, string | string[]>;

export default defineComponent({
  name: 'BusinessQuestionsGroupStep',
  props: {
    /** Tolgee key for the step title (e.g. biz_wizard_group_a_title). */
    titleKey: { type: String, required: true },
    /** Optional Tolgee key for a short paragraph below the title. */
    descriptionKey: { type: String, default: null },
    /** Questions to render in this step. Already sorted by sort_order. */
    questions: {
      type: Array as PropType<QuestionDef[]>,
      required: true,
    },
    /** Two-way bound answer map keyed by question.id. */
    modelValue: {
      type: Object as PropType<AnswerMap>,
      required: true,
    },
  },
  emits: ['update:modelValue'],
  data() {
    return {
      openHelp: new Set<string>(),
    };
  },
  methods: {
    toggleHelp(questionId: string): void {
      // Set is reactive when we replace it (otherwise Vue 3 can't
      // track mutations on built-in Set without explicit re-assign).
      const next = new Set(this.openHelp);
      if (next.has(questionId)) next.delete(questionId);
      else next.add(questionId);
      this.openHelp = next;
    },
    isSelected(questionId: string, option: string): boolean {
      return this.modelValue[questionId] === option;
    },
    isInMultiSelect(questionId: string, option: string): boolean {
      const v = this.modelValue[questionId];
      return Array.isArray(v) && v.includes(option);
    },
    setAnswer(questionId: string, option: string): void {
      this.$emit('update:modelValue', {
        ...this.modelValue,
        [questionId]: option,
      });
    },
    toggleMultiSelect(questionId: string, option: string): void {
      const current = this.modelValue[questionId];
      const arr = Array.isArray(current) ? [...current] : [];
      const idx = arr.indexOf(option);
      if (idx >= 0) arr.splice(idx, 1);
      else arr.push(option);
      this.$emit('update:modelValue', {
        ...this.modelValue,
        [questionId]: arr,
      });
    },
    /** Tolgee key for a question's option label. Convention:
     *  biz_q_<question_id_lowercase>_opt_<option_value_lowercase>.
     *  The hidden whitelist span in BusinessQuestionsWizard registers
     *  every key (all lowercase suffixes).
     *
     *  DOCB-12181: option values for Q-A2 (ZUGFeRD profiles) became
     *  UPPERCASE on the backend so the persisted attribute round-trips
     *  through the Acceptance-Gate UI. Tolgee keys stay lowercase
     *  (matches the original authoring + other questions like A1
     *  version numbers, B1/B2 yes/no). Lowercase the suffix so the
     *  lookup resolves; missing-key fallback would leak the raw key
     *  text to the wizard and fail the raw-key-guard playwright spec.
     */
    optionLabel(questionId: string, option: string): string {
      const key = `biz_q_${questionId.toLowerCase()}_opt_${String(option).toLowerCase()}`;
      return this.$t(key);
    },
  },
});
</script>

