<template>
  <button
    type="button"
    class="profile-card"
    :class="{ 'profile-card--selected': selected }"
    :data-test="`profile-card-${profile.id}`"
    :aria-pressed="selected"
    @click="$emit('select', profile.id)"
  >
    <!-- Inline-SVG icon per profile. No MDI-bundle dependency — see
         BOL-438 pattern. Geometry chosen to read at 22 px. -->
    <div class="profile-icon" aria-hidden="true">
      <component :is="iconComponent" />
    </div>

    <div class="profile-content">
      <div class="profile-header-row">
        <span class="profile-label">{{ $t(profile.label_key) }}</span>
        <span v-if="profile.is_default" class="profile-default-badge">
          {{ $t('biz_wizard_default_badge') }}
        </span>
      </div>
      <p class="profile-description">{{ $t(profile.description_key) }}</p>

      <div class="profile-summary">
        <span class="profile-summary-chip">
          {{ summaryStrictness }}
        </span>
        <span class="profile-summary-chip">
          {{ profile.accepted_versions.length }}
          {{ $t('biz_wizard_summary_versions') }}
        </span>
        <span v-if="profile.vies_enabled" class="profile-summary-chip profile-summary-chip--on">
          VIES
        </span>
        <span v-if="profile.blocking_enabled" class="profile-summary-chip profile-summary-chip--on">
          {{ $t('biz_wizard_summary_blocking') }}
        </span>
      </div>
    </div>

    <div class="profile-radio" aria-hidden="true">
      <svg
        v-if="selected"
        viewBox="0 0 24 24"
        xmlns="http://www.w3.org/2000/svg"
        class="profile-radio-icon"
      >
        <path
          d="M9 16.17l-3.88-3.88-1.41 1.41L9 19 21 7l-1.41-1.41z"
          fill="currentColor"
        />
      </svg>
    </div>
  </button>
</template>

<script lang="ts">
import { defineComponent, h, type PropType } from 'vue';
import type {
  ProfileDef,
  Preset,
} from 'src/services/settings/PolicyWizardApiService';

// Inline-SVG functional renderers — one per profile. Keeping them as
// h()-based render functions inside the same file avoids extra .vue
// files for tiny presentational icons.
const IconB2G = () =>
  h(
    'svg',
    { viewBox: '0 0 24 24', xmlns: 'http://www.w3.org/2000/svg' },
    [
      h('path', {
        d: 'M12 2L2 7v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V7l-10-5zm-1.06 14L7 12.06l1.41-1.41 2.53 2.53 5.66-5.66L18 8.94 10.94 16z',
        fill: 'currentColor',
      }),
    ],
  );

const IconB2BDomestic = () =>
  h(
    'svg',
    { viewBox: '0 0 24 24', xmlns: 'http://www.w3.org/2000/svg' },
    [
      h('path', {
        d: 'M12 3L4 9v12h5v-7h6v7h5V9l-8-6zm0 2.45L18 9.55V19h-3v-7H9v7H6V9.55l6-4.1z',
        fill: 'currentColor',
      }),
    ],
  );

const IconB2BEU = () =>
  h(
    'svg',
    { viewBox: '0 0 24 24', xmlns: 'http://www.w3.org/2000/svg' },
    [
      h('path', {
        d: 'M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 2c1.78 0 3.42.59 4.75 1.58L5.58 16.75A7.95 7.95 0 014 12c0-4.42 3.58-8 8-8zm0 16a7.95 7.95 0 01-4.75-1.58L18.42 7.25A7.95 7.95 0 0120 12c0 4.42-3.58 8-8 8z',
        fill: 'currentColor',
      }),
    ],
  );

const IconMigration = () =>
  h(
    'svg',
    { viewBox: '0 0 24 24', xmlns: 'http://www.w3.org/2000/svg' },
    [
      h('path', {
        d: 'M19.35 10.04A7.49 7.49 0 0012 4C9.11 4 6.6 5.64 5.35 8.04 2.34 8.36 0 10.91 0 14a6 6 0 006 6h13a5 5 0 005-5c0-2.64-2.05-4.78-4.65-4.96zM19 18H6a4 4 0 010-8c.14 0 .27.02.4.04A5.49 5.49 0 0112 6a5.49 5.49 0 015.6 4.04c.13-.02.26-.04.4-.04a3 3 0 010 6v2z',
        fill: 'currentColor',
      }),
    ],
  );

const IconCustom = () =>
  h(
    'svg',
    { viewBox: '0 0 24 24', xmlns: 'http://www.w3.org/2000/svg' },
    [
      h('path', {
        d: 'M19.14 12.94a7.78 7.78 0 000-1.88l2.03-1.58a.5.5 0 00.12-.64l-1.92-3.32a.5.5 0 00-.61-.22l-2.39.96a7.5 7.5 0 00-1.62-.94l-.36-2.54a.5.5 0 00-.5-.42h-3.84a.5.5 0 00-.5.42l-.36 2.54a7.5 7.5 0 00-1.62.94l-2.39-.96a.5.5 0 00-.61.22L2.65 8.84a.5.5 0 00.12.64l2.03 1.58a7.78 7.78 0 000 1.88l-2.03 1.58a.5.5 0 00-.12.64l1.92 3.32a.5.5 0 00.61.22l2.39-.96a7.5 7.5 0 001.62.94l.36 2.54a.5.5 0 00.5.42h3.84a.5.5 0 00.5-.42l.36-2.54a7.5 7.5 0 001.62-.94l2.39.96a.5.5 0 00.61-.22l1.92-3.32a.5.5 0 00-.12-.64l-2.03-1.58zM12 15.5a3.5 3.5 0 110-7 3.5 3.5 0 010 7z',
        fill: 'currentColor',
      }),
    ],
  );

const ICON_BY_PROFILE: Record<string, () => unknown> = {
  b2g_public_sector: IconB2G,
  b2b_domestic: IconB2BDomestic,
  b2b_eu_cross_border: IconB2BEU,
  migration_testing: IconMigration,
  custom: IconCustom,
};

export default defineComponent({
  name: 'BusinessQuestionsProfileCard',
  props: {
    profile: {
      type: Object as PropType<ProfileDef>,
      required: true,
    },
    selected: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['select'],
  computed: {
    iconComponent() {
      return ICON_BY_PROFILE[this.profile.id] ?? IconCustom;
    },
    /** "All Strict" / "All Standard" / "All Lax" / "Mixed". Reads
     *  the resolved preset map so a custom profile that drifts from
     *  uniform shows up as "Mixed" without us hardcoding labels. */
    summaryStrictness(): string {
      const presets = Object.values(
        this.profile.category_presets,
      ) as Preset[];
      const unique = new Set(presets);
      if (unique.size === 1) {
        const only = [...unique][0];
        return this.$t(`biz_wizard_summary_all_${only}`);
      }
      return this.$t('biz_wizard_summary_mixed');
    },
  },
});
</script>

